#pragma once

#include <cstdint>

#include <cinerig/math/quat.hpp>
#include <cinerig/math/vec.hpp>

namespace cinerig
{

// Engine handles are opaque, stable values owned by the host application.
// A value of 0 is reserved for "no entity" and is never generated by CineRig.
using EntityId = std::uint64_t;
using CameraId = std::uint64_t;
using SplineId = std::uint64_t;
using GroupId = std::uint64_t;

enum class UpdateClock : std::uint8_t
{
    Fixed,
    Late,
};

// The host application owns the transform storage. CineRig only reads it,
// except through the optional trySetTransform() hook.
struct Transform
{
    math::Vec3 position{};
    math::Quat rotation{};
    math::Vec3 scale{1.0f, 1.0f, 1.0f};
};

// Non-owning adapter to the host entity database. The implementation must
// remain valid for the lifetime of the object using it.
class IEntityWorld
{
public:
    virtual ~IEntityWorld() = default;

    virtual bool exists(EntityId id) const = 0;

    // Returns an identity transform when the entity does not exist. Call
    // exists() first when missing entities are meaningful to the caller.
    virtual Transform transform(EntityId id) const = 0;

    // Optional write-back hook for virtual cameras that own a host transform.
    // Returning false means the entity is read-only; the caller must keep its
    // own state instead. The default implementation is read-only.
    virtual bool trySetTransform(EntityId id, const Transform& transform)
    {
        (void)id;
        (void)transform;
        return false;
    }

    // Used by SmartUpdate to decide whether a target changed in the fixed or
    // late clock. The conservative default is Late.
    virtual UpdateClock lastChangeClock(EntityId id) const
    {
        (void)id;
        return UpdateClock::Late;
    }

    // Time is in seconds. A negative deltaTime means "do not apply
    // time-dependent updates this frame".
    virtual float deltaTime(UpdateClock clock) const = 0;
    virtual float fixedDeltaTime() const = 0;
    virtual float time() const = 0;

    // Optional unscaled time hooks. Adapters that support pausing or
    // slow-motion override these; the defaults preserve scaled time.
    virtual float unscaledDeltaTime(UpdateClock clock) const
    {
        return deltaTime(clock);
    }

    virtual float unscaledTime() const
    {
        return time();
    }

    // Late returns the global render frame, Fixed the fixed-step frame.
    virtual std::uint64_t frame(UpdateClock clock) const = 0;

    virtual math::Vec3 worldUp() const = 0;

    // Viewport dimensions in pixels. The width/height ratio is the output
    // camera aspect used by screen-space composition.
    virtual math::Vec2 viewportSize() const = 0;
};

}
